    ["2026-11-11T17:00:00Z","2026-11-11T18:00:00Z","Spec Check","Spec Check - Episode 1","The ultimate Pickleball gear review show revealing the sport's latest technology and newest products","https://dh7h3upxwg7do.cloudfront.net/Images/S3/pkbl/SPEC_CHECK_16x9.jpg",0,0],
    ["2026-11-11T18:00:00Z","2026-11-11T20:00:00Z","MLP Champions Series","MLP Champions Series: Dallas TeamBattle","MLP Champions Series: Dallas TeamBattle Part 1 -","https://dh7h3upxwg7do.cloudfront.net/Images/S3/pkbl/MLPChampionshipSeries16x9.jpg",0,0],
