    ["2026-11-11T20:30:00Z","2026-11-12T00:00:00Z","Major League Pickleball","MLP Nations Cup 2026: Day 3","Pickleball coverage from MLP Nations Cup 2026","https://dh7h3upxwg7do.cloudfront.net/Images/S3/pkbl/MLPNC16x9.jpg",0,0],
    ["2026-11-12T00:00:00Z","2026-11-12T02:00:00Z","PPA Tour Pickleball","Pickleball World Championships: Round of 16","Pickleball coverage from PPA Tour: Pickleball World Championships","https://dh7h3upxwg7do.cloudfront.net/Images/S3/pkbl/PPA_WORLDS26_16x9.jpg",0,0],
    ["2026-11-12T02:00:00Z","2026-11-12T03:00:00Z","Spec Check","Spec Check - Episode 1","The ultimate Pickleball gear review show revealing the sport's latest technology and newest products","https://dh7h3upxwg7do.cloudfront.net/Images/S3/pkbl/SPEC_CHECK_16x9.jpg",0,0],
    ["2026-11-12T03:00:00Z","2026-11-12T04:00:00Z","Pickleballers Podcast","Featuring Lacy Schneeman","Pickleballers Podcast with featured guest Lacy Schneeman","https://dh7h3upxwg7do.cloudfront.net/Images/S3/PickleballersPOD169.jpg",0,0],
    ["2026-11-12T04:00:00Z","2026-11-12T10:00:00Z","PPA Tour Pickleball","Pickleball World Championships: Championship Sunday","Pickleball coverage from PPA Tour: Pickleball World Championships","https://dh7h3upxwg7do.cloudfront.net/Images/S3/pkbl/PPA_WORLDS26_16x9.jpg",0,0],
    ["2026-11-12T10:00:00Z","2026-11-12T11:00:00Z","Pickleballers Podcast","Featuring Fedrico Staksrud","Pickleballers Podcast with featured guest Fedrico Staksrud","https://dh7h3upxwg7do.cloudfront.net/Images/S3/PickleballersPOD169.jpg",0,0],
    ["2026-11-12T11:00:00Z","2026-11-12T11:30:00Z","PBTV Big Shots","Episode 6","PBTV Big Shots Episode 6","https://dh7h3upxwg7do.cloudfront.net/Images/S3/PBTVBIGSHOTS16x9.png",0,0],
    ["2026-11-12T11:30:00Z","2026-11-12T12:30:00Z","Pickleballers Podcast","Featuring Grayson Goldin","Pickleballers Podcast with featured guest Grayson Goldin","https://dh7h3upxwg7do.cloudfront.net/Images/S3/PickleballersPOD169.jpg",0,0],
    ["2026-11-12T12:30:00Z","2026-11-12T13:00:00Z","Pickleball Eats","Pickleball Eats: Hannah Blatt and Grayson Goldin","Top pickleball pros take you behind the scenes of their favorite restaunts on tour","https://dh7h3upxwg7do.cloudfront.net/Images/S3/pkbl/PickleballEats16x9.jpg",0,0]
  ];

  const LABEL = { original: "PBTV Original", mlp: "MLP", ppa: "PPA Tour", tba: "TBA" };
  const MO = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
  const WD = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
  const ET_FMT = new Intl.DateTimeFormat("en-US", { timeZone: "America/New_York", hourCycle: "h23", year: "numeric", month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit" });

  let slots = [];          // { start, stop, title, sub, desc, icon, premiere, kind, day }
  let source = "none";     // "live" | "saved" | "none"
  let loadedAt = null;
  let selected = null;

  function esc(s) { return String(s).replace(/[&<>"]/g, c => ({ "&": "&", "<": "<", ">": ">", '"': """ })[c]); }
  function et(date) {
    const parts = ET_FMT.formatToParts(date), g = t => parts.find(p => p.type === t).value;
    return { day: g("year") + "-" + g("month") + "-" + g("day"), h: Number(g("hour")) % 24, m: Number(g("minute")) };
  }
  function clock(date) { const t = et(date); return (((t.h + 11) % 12) + 1) + ":" + String(t.m).padStart(2, "0") + " " + (t.h >= 12 ? "PM" : "AM"); }
  function dayInfo(day) { const [y, m, d] = day.split("-").map(Number); return { m, d, wd: WD[new Date(Date.UTC(y, m - 1, d)).getUTCDay()] }; }
  function kindOf(title) {
    if (/^to be announced$/i.test(title)) return "tba";
    if (/^PPA/.test(title)) return "ppa";
    if (/^(Major League Pickleball|MLP)/.test(title)) return "mlp";
    return "original";
  }
  function makeSlot(start, stop, title, sub, desc, icon, premiere, live) {
    title = title.trim(); sub = (sub || "").trim();
    if (sub.startsWith(title + ": ")) sub = sub.slice(title.length + 2);
    const s = { start, stop, title, sub, desc: (desc || "").trim(), icon: icon || "", premiere: !!premiere, live: !!live, kind: kindOf(title) };
    s.day = et(start).day;
    return s;
  }
  // XMLTV times look like 2026-10-20T10:00:00.000+0000; add the colon so every browser parses them.
  function xmltvDate(v) { return new Date(String(v).replace(/([+-]\d{2})(\d{2})$/, "$1:$2")); }

  function parseFeed(text) {
    const doc = new DOMParser().parseFromString(text, "application/xml");
    if (doc.querySelector("parsererror")) throw new Error("Guide feed is not valid XML");
    const out = [...doc.getElementsByTagName("programme")].map(p => {
      const txt = tag => (p.getElementsByTagName(tag)[0] || {}).textContent || "";
      const icon = p.getElementsByTagName("icon")[0];
      return makeSlot(xmltvDate(p.getAttribute("start")), xmltvDate(p.getAttribute("stop")), txt("title"), txt("sub-title"), txt("desc"),
        icon ? icon.getAttribute("src") : "", p.getElementsByTagName("premiere").length > 0,
        // Live events carry the XMLTV  tag and an AiringType of "Live"; either one marks the program live.
        p.getElementsByTagName("live").length > 0 || /^\s*live\s*$/i.test(txt("AiringType")));
    }).filter(s => !isNaN(s.start) && !isNaN(s.stop));
    if (!out.length) throw new Error("Guide feed has no programs");
    return out.sort((a, b) => a.start - b.start);
  }

  async function load() {
    try {
      const res = await fetch(FEED_URL, { cache: "no-cache" });
      if (!res.ok) throw new Error("Guide feed returned " + res.status);
      slots = parseFeed(await res.text());
      source = "live"; loadedAt = new Date();
    } catch (err) {
      console.warn("Using saved schedule:", err);
      if (source !== "live") {   // keep a good live copy over the saved one
        slots = FALLBACK.map(r => makeSlot(new Date(r[0]), new Date(r[1]), r[2], r[3], r[4], r[5], r[6], r[7]));
        source = "saved";
      }
    }
    render();
  }

  // ---- rendering ----
  const daysEl = document.getElementById("days");
  const schedEl = document.getElementById("sched");

  function visibleDays(now) {
    const today = et(now).day;
    return [...new Set(slots.map(s => s.day))].filter(d => d >= today).sort();
  }

  function renderDays(days, today, now) {
    daysEl.innerHTML = "";
    days.forEach(day => {
      const d = dayInfo(day);
      const b = document.createElement("button");
      b.type = "button"; b.className = "day"; b.id = "day-" + day;
      b.setAttribute("role", "tab");
      b.setAttribute("aria-selected", String(day === selected));
      b.setAttribute("aria-controls", "sched");
      b.tabIndex = day === selected ? 0 : -1;
      const hasLive = slots.some(s => s.day === day && s.live && s.stop > now);
      b.innerHTML = '' + MO[d.m - 1] + '' + d.d + '' + (day === today ? "Today" : d.wd) + "" +
        (hasLive ? ', live event' : "");
      b.addEventListener("click", () => select(day, false));
      daysEl.appendChild(b);
    });
  }
  function select(day, focus) {
    selected = day; render();
    const btn = document.getElementById("day-" + day);
    if (btn) { if (focus) btn.focus(); btn.scrollIntoView({ block: "nearest", inline: "nearest" }); }
  }
  daysEl.addEventListener("keydown", e => {
    const days = visibleDays(new Date()), k = days.indexOf(selected);
    if (e.key === "ArrowRight" && k < days.length - 1) { e.preventDefault(); select(days[k + 1], true); }
    if (e.key === "ArrowLeft" && k > 0) { e.preventDefault(); select(days[k - 1], true); }
  });

  function renderSched(now, today) {
    const head = document.getElementById("sched-h");
    schedEl.innerHTML = "";
    if (!selected) {
      head.textContent = "Today's lineup";
      schedEl.innerHTML = source === "none"
        ? '
Loading the channel guide.'
        : '
The schedule isn\'t available right now.
The live channel plays 24/7. Tune in any time.';
      return;
    }
    const d = dayInfo(selected);
    head.textContent = selected === today ? "Today's lineup" : d.wd + ", " + MO[d.m - 1] + " " + d.d;
    schedEl.setAttribute("aria-labelledby", "day-" + selected);
    const list = slots.filter(s => s.day === selected);
    const confirmed = list.filter(s => s.kind !== "tba").length;
    if (!confirmed) {
      schedEl.innerHTML = '
Programming for ' + MO[d.m - 1] + " " + d.d + " is still being set.
Check back soon. The live channel plays 24/7 in the meantime.";
      return;
    }
    list.forEach(s => {
      const isNow = s.start <= now && now < s.stop, isPast = s.stop <= now, tba = s.kind === "tba";
      const el = document.createElement("div");
      el.className = "row" + (isNow ? " now" : "") + (s.live ? " is-live" : "") + (isPast ? " past" : "") + (tba ? " tba" : "");
      const tag = s.live && !isPast ? 'Live'
        : s.premiere && !isPast ? 'Premiere'
        : '' + LABEL[s.kind] + "";
      el.innerHTML =
        '
' + clock(s.start) + "" + (isNow ? (s.live ? "Live now" : "On now") : "ET") + "" +
        '

' + esc(tba ? "To be announced" : s.title) + "" + (s.sub ? '
' + esc(s.sub) + "" : "") + "" +
        '
' + (isNow ? 'Watch live' : tag) + "";
      if (s.desc && !tba) el.title = s.desc;
      schedEl.appendChild(el);
    });
    if (confirmed < list.length) {
      const n = document.createElement("p");
      n.className = "tz"; n.style.marginTop = "14px";
      n.textContent = "Slots marked TBA will be filled as programming is confirmed.";
      schedEl.appendChild(n);
    }
  }

  function renderOnNow(now) {
    const cur = slots.find(s => s.start <= now && now < s.stop);
    const nxt = slots.find(s => s.start >= (cur ? cur.stop : now) && s.kind !== "tba");
    const title = document.getElementById("now-title"), sub = document.getElementById("now-sub"), next = document.getElementById("now-next");
    const art = document.getElementById("now-art"), screen = art.parentElement;
    const real = cur && cur.kind !== "tba";
    const liveNow = !!(real && cur.live);
    document.getElementById("now-badge").classList.toggle("onair", liveNow);
    document.getElementById("now-badge-text").textContent = liveNow ? "Live" : "On air";
    title.textContent = real ? cur.title : "PickleballTV Live";
    sub.textContent = real ? (cur.sub || cur.desc) : "The 24/7 channel, streaming now";
    if (real && cur.icon) {
      if (art.getAttribute("src") !== cur.icon) art.src = cur.icon;
      art.hidden = false; screen.classList.add("has-art");
    } else { art.hidden = true; art.removeAttribute("src"); screen.classList.remove("has-art"); }
    if (nxt) {
      const when = (nxt.day === et(now).day ? "" : dayInfo(nxt.day).wd + " ") + clock(nxt.start) + " ET";
      next.innerHTML = "Up next" + when + "" + esc(nxt.title) + "" + (nxt.live ? 'Live' : "");
    } else next.innerHTML = "More programming is being added. Check the schedule below.";
  }

  function renderStatus(now) {
    document.getElementById("tz-note").textContent = "Times shown in Eastern. It's " + clock(now) + " ET.";
    const st = document.getElementById("feed-status");
    st.textContent = source === "live" ? "Guide updated " + clock(loadedAt) + " ET."
      : source === "saved" ? "Showing a saved copy of the guide. It may be out of date." : "";
  }

  function render() {
    const now = new Date(), today = et(now).day, days = visibleDays(now);
    if (!days.includes(selected)) selected = days[0] || null;
    renderDays(days, today, now);
    renderSched(now, today);
    renderOnNow(now);
    renderStatus(now);
  }

  // Footer "Cookie Preferences" reopens the Ketch consent panel. Calls queue until Ketch has loaded.
  document.getElementById("cookie-prefs").addEventListener("click", () => { if (window.ketch) window.ketch("showPreferences"); });

  render();
  load();
  setInterval(render, TICK_MS);
  setInterval(load, REFRESH_MS);
  document.addEventListener("visibilitychange", () => { if (!document.hidden) load(); });
})();
